import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _isLoadingMore = false;
  bool _hasMore = true;
  String _searchQuery = '';

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final repository = context.read<CurrencyRepository>();

    _currencyListFuture = repository.fetchRates(const CurrencyPageRequest()).then((CurrencyPage page) {
      final List<CurrencyModel> value = page.items;
      _allCurrencies = value;
      _hasMore = page.hasMore;
      _filteredCurrenciesNotifier = ValueNotifier(_applyFilter(value, _searchQuery));

      _fadeController.forward(); // запускаем анимацию

      repository.saveCurrencyList(value);

      return value;
    });
  }

  List<CurrencyModel> _applyFilter(List<CurrencyModel> list, String query) {
    if (query.isEmpty) return list;
    final lowerQuery = query.toLowerCase();
    return list.where((currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    }).toList(growable: false);
  }

  Future<void> _loadNextPage() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    try {
      final repository = context.read<CurrencyRepository>();
      final nextPage = await repository.fetchRates(CurrencyPageRequest(page: _currentPage + 1));

      if (!mounted) return;

      setState(() {
        _currentPage++;
        _hasMore = nextPage.hasMore;
        _allCurrencies.addAll(nextPage.items);
        _filteredCurrenciesNotifier.value = _applyFilter(_allCurrencies, _searchQuery);
      });

      repository.saveCurrencyList(_allCurrencies);
    } catch (_) {
      // nothing to do – button stays enabled so user can retry
    } finally {
      if (mounted) setState(() => _isLoadingMore = false);
    }
  }

  void _filterCurrencies(String query) {
    _searchQuery = query;
    _filteredCurrenciesNotifier.value = _applyFilter(_allCurrencies, query);
  }

  Widget _buildShowMoreButton() {
    if (_isLoadingMore) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 16),
        child: Text(context.loc.loading, style: context.fonts.regular12.copyWith(color: context.colors.stormyGrey)),
      );
    }

    if (!_hasMore || _allCurrencies.isEmpty) {
      return const SizedBox.shrink();
    }

    return Padding(
      padding: const EdgeInsets.fromLTRB(22, 0, 22, 16),
      child: SizedBox(
        width: double.infinity,
        height: 48,
        child: ElevatedButton(
          onPressed: _loadNextPage,
          style: ElevatedButton.styleFrom(backgroundColor: context.colors.primary),
          child: Text(context.loc.searchMore, style: context.fonts.semiBold12.copyWith(color: Colors.white)),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> listData, _) {
                      return ListView.builder(
                        itemCount: listData.length,
                        itemBuilder: (BuildContext context, int index) {
                          final CurrencyModel currency = listData[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 16),
                      );
                    },
                  ),
                ),
                _buildShowMoreButton(),
              ],
            ),
          );
        },
      ),
    );
  }
}
